function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 100000) return 'nums needs 2 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -100000 || v > 100000)) return 'Each value of nums is an integer from -10^5 to 10^5.';
  if (!Number.isInteger(k) || k < -100000 || k > 100000) return 'k is an integer from -10^5 to 10^5.';
  return null;
}

