function waysToPartition(nums, k) {
  const n = nums.length;
  const total = nums.reduce((sum, value) => sum + value, 0);
  const add = (map, key, step) => map.set(key, (map.get(key) ?? 0) + step);
  const left = new Map();
  const right = new Map();
  let prefix = 0;

  for (let pivot = 1; pivot < n; pivot++) {
    prefix += nums[pivot - 1];
    add(right, 2 * prefix - total, 1);
  }
  let best = right.get(0) ?? 0;

  prefix = 0;
  for (let i = 0; i < n; i++) {
    const delta = k - nums[i];
    best = Math.max(best, (left.get(delta) ?? 0) + (right.get(-delta) ?? 0));
    if (i + 1 < n) {
      prefix += nums[i];
      const gap = 2 * prefix - total;
      add(right, gap, -1);
      add(left, gap, 1);
    }
  }
  return best;
}

