function waysToPartition(nums, k) {
  const count = (arr) => {
    let ways = 0;
    for (let p = 1; p < arr.length; p++) {
      let before = 0, after = 0;
      for (let j = 0; j < arr.length; j++) if (j < p) before += arr[j]; else after += arr[j];
      if (before === after) ways++;
    }
    return ways;
  };
  let best = count(nums);
  for (let i = 0; i < nums.length; i++) best = Math.max(best, count(nums.map((v, j) => (j === i ? k : v))));
  return best;
}

