function generate(rand, size) {
  const n = size === 'large' ? 2000 : 2 + Math.floor(rand() * 7);
  const spans = size === 'large' ? [2, 5, 40] : [1, 2, 3, 6];
  const span = spans[Math.floor(rand() * spans.length)];
  const value = (s) => Math.floor(rand() * (2 * s + 1)) - s;
  return [Array.from({ length: n }, () => value(span)), value(2 * span)];
}
